require('base/class')

local employee_class = newclass('SuccubusEmployee')

--- public struct EmployeeData
---		{
---			public int Sales;
---			public int Id;
---			public int Condition;
---     }
function employee_class:init(init_data)
	-- setup from server data
	self.id = init_data.Id
	self.condition = init_data.Condition
	self.sales = init_data.Sales

	self.spec = CS.Oak.SuccubusCafeData.GetEmployeeSpec(self.id)
end

function employee_class:level()
	return CS.Oak.SuccubusConstants.GetOrCreate().GetEmployeeLevel(self.sales)
end


return {
	create = function(init_data)
		return employee_class(init_data)
	end
}

