--region 타겟 객체 만들기 규칙
--[[
target = {
	line_data.wave_#.targets 테이블에 들어갈 키값 이름
	a = {
		score : 해동 타겟을 맞추면 얻는 점수 (점수가 음수면 함정 처럼 사용 가능)
		name : 스테틱 데이터에 등록된 캐릭터 이름 (타일맵 npc들 따로 배치할 필요 없음)
		direction = 방향 (default : down)
		anim = {
			name = 애니메이션 이름 (default: idle)
			loop = 애니메이션 루프 (default: false)
		}
		emotion = 표정 (default: idle)
		scale_factor = 캐릭터 크기 (default: 1)
	}
}
]]
--endregion
--region 웨이브 설정 규칙
--[[
wave = {
	인덱스로 #번째 웨이브 접근
	{
		line_1 = {
			-- 원하는 타겟 타입의 키값을 원하는 수 만큼 넣어서 사용
			-- a 타입 스폰 -> b 타입 스폰 -> a타입 스폰 하겠다는 예시
			targets = { 'a', 'b', 'a' },
			spawn_delay = {1, 2, 1} (첫 번째 타겟 1초뒤 스폰, 두 번째 타겟 2초 뒤 스폰, 세 번째 타겟 1초 뒤 스폰)
			spawn_marker = 타겟이 나타나는 위치
			dest_marker = 타겟이 이동하는 위치
		},
		-- 웨이브 별로 사용할 라인 만큼 설정하기
		line_# = ...
	},
}
]]
--endregion

--region line_num 규칙
-- 라인 숫자 만큼 zone을 만들어 주세요.
-- 총알 충돌 검사 최적화에 라인 존의 바운드 필요****
-- 존의 이름은 (line_#으로 통일)
--endregion

