--region 베이스 노드
local bt_creator = newclass('RunningGameBaseBTCreator')

function bt_creator:init()
	self.node_prototypes = {}
	self:load_node_prototype('minigame/RunningGame/Sequence/RunningGameSequence')
end

function bt_creator:load_node_prototype(path)
	local nodes = get_or_create_global_variable(path)

	for k, v in pairs(nodes) do
		self.node_prototypes[k] = v
	end
end

function bt_creator:create_node(node_type, bt_builder, data)
	local type = self.node_prototypes[node_type]
	local instance = type(bt_builder, data)

	return instance
end

return {
	create = function()
		return bt_creator()
	end
}

